shaderSource:
uniform float2 resolution;
uniform float tiltX;
uniform float tiltY;

half4 main(float2 xy) {
  float2 uv = xy / max(resolution, float2(1.0, 1.0));
  float aspect = resolution.x / max(resolution.y, 1.0);
  float2 light = float2(0.35, 0.18) + float2(tiltX, tiltY) * 0.32;

  float band = uv.x * 1.35 + uv.y * 0.55 + tiltX * 0.4 + tiltY * 0.25;
  float metal = 0.42 + 0.38 * sin(band * 6.28318);
  metal = mix(metal, 0.85, smoothstep(0.35, 0.55, fract(band)));

  half3 dark = half3(0.28, 0.30, 0.34);
  half3 bright = half3(0.92, 0.94, 0.98);
  half3 cool = half3(0.62, 0.72, 0.88);
  half3 warm = half3(0.88, 0.82, 0.72);
  half3 col = mix(dark, bright, metal);
  col = mix(col, cool, 0.22 + tiltX * 0.12);
  col = mix(col, warm, 0.12 + max(0.0, -tiltY) * 0.15);

  float2 e = min(uv, 1.0 - uv);
  float rim = 1.0 - smoothstep(0.0, 0.09, min(e.x * aspect, e.y));
  col = mix(col * 0.55, col + half3(0.25, 0.28, 0.32), 1.0 - rim * 0.85);
  col += half3(1.0, 1.0, 1.0) * rim * 0.35;

  float2 d = uv - light;
  d.x *= aspect;
  float spec = exp(-dot(d, d) * 28.0);
  float streak = exp(-pow(d.x * 1.8 + d.y * 0.35, 2.0) * 40.0) * exp(-abs(d.y) * 8.0);
  col += half3(1.0, 1.0, 1.0) * (spec * 1.05 + streak * 0.55);

  float shade = smoothstep(0.0, 1.0, uv.y);
  col *= mix(1.12, 0.72, shade);

  return half4(col, 1.0);
}
